sql.where:
t.deleted = 0

    AND t.report_no LIKE CONCAT('%', #{req.reportNo}, '%')


    AND t.prod_order_id = #{req.prodOrderId}


    AND t.work_order_id = #{req.workOrderId}


    AND t.op_task_id = #{req.opTaskId}


    AND t.worker_id = #{req.workerId}


    AND t.res_id = #{req.resId}


    AND t.shift_id = #{req.shiftId}


    AND t.status = #{req.status}


    AND t.report_time BETWEEN #{req.reportTime[0]} AND #{req.reportTime[1]}


    AND t.create_time BETWEEN #{req.createTime[0]} AND #{req.createTime[1]}
